def get_total_number_of_sequences(n, m):
    """
    Returns the number of possible sequences of length n such that each next element is 
    greater than or equal to twice the previous element.

    The sequence elements are positive integers within the range from 1 to a given maximum value m.
    """
    if n <= 0 or m <= 0:
        return 0

    # dp[i][x] = number of sequences of length i ending with element x
    dp = [ [0] * (m+1) for _ in range(n+1)]

    # Base case: sequences of length 1
    for x in range(1, m+1):
        dp[1][x] = 1

    for length in range(2, n+1):
        # To optimize, precompute prefix sums of dp[length-1]
        prefix_sum = [0] * (m+2)  # 1-based indexing, extra padding
        for x in range(1, m+1):
            prefix_sum[x] = prefix_sum[x-1] + dp[length-1][x]

        for x in range(1, m+1):
            # The previous element must be <= x // 2
            max_prev = x // 2
            if max_prev >= 1:
                dp[length][x] = prefix_sum[max_prev]
            else:
                dp[length][x] = 0

    return sum(dp[n][1:m+1])
